function kick(p){if(phase!=='play'||p.kickCd>0||ball.glued===p)return;const dx=ball.x-p.x,dy=ball.y-p.y,d=hypot(dx,dy);if(d>p.r+ball.r+27)return;let nx=d?dx/d:p.faceX,ny=d?dy/d:p.faceY;if(!p.human){const goalY=p.team===0?field.y-30:field.y+field.h+30,aimX=W/2-ball.x,aimY=goalY-ball.y,l=hypot(aimX,aimY)||1;nx=aimX/l;ny=aimY/l;}if(!nx&&!ny)ny=p.team===0?-1:1;const force=powerEffect?.type==='fire'&&p.team===0?780:540;p.kickCd=.32;ball.vx+=nx*force+p.vx*.48;ball.vy+=ny*force+p.vy*.48;const speed=hypot(ball.vx,ball.vy),max=powerEffect?.type==='fire'&&p.team===0?890:640;if(speed>max){ball.vx*=max/speed;ball.vy*=max/speed;}ball.glued=null;p.kickFlash=.18;particleBurst(ball.x,ball.y,p.pesi?gold:p.color,12,1.15);shake=Math.max(shake,2.4);}
function activateGlue(p){if(!p?.pesi||p.glueCd>0||p.glue>0||phase!=='play')return false;const d=hypot(ball.x-p.x,ball.y-p.y);if(d>p.r+ball.r+58)return false;p.glue=GLUE_TIME;p.glueCd=GLUE_CD;ball.glued=p;ball.vx=ball.vy=0;glueMsg='✦  GLUE DRIBBLE ACTIVE';glueMsgTime=.9;particleBurst(p.x,p.y,gold,20,.75);return true;}
function finishGlue(p){if(ball.glued!==p)return;const mates=players.filter(q=>q.team===p.team&&q!==p);const goalY=field.y-20,goalDx=W/2-ball.x,goalDy=goalY-ball.y,goalDist=hypot(goalDx,goalDy)||1;const angle=Math.abs(goalDx/goalDist);let clear=angle<.31;for(const q of players){if(q.team===p.team)continue;const vx=goalDx/goalDist,vy=goalDy/goalDist,along=(q.x-ball.x)*vx+(q.y-ball.y)*vy;if(along>0&&along<goalDist&&Math.abs((q.x-ball.x)*vy-(q.y-ball.y)*vx)<q.r+14)clear=false;}let tx,ty,force;if(clear){tx=goalDx/goalDist;ty=goalDy/goalDist;force=610;glueMsg='✦  GLUE FINISH · SHOT!';}else{const mate=mates.sort((a,b)=>hypot(a.x-ball.x,a.y-ball.y)-hypot(b.x-ball.x,b.y-ball.y))[0];if(mate){const lead=Math.min(.38,hypot(mate.vx,mate.vy)/500);tx=mate.x+mate.vx*lead-ball.x;ty=mate.y+mate.vy*lead-ball.y;}else{tx=goalDx;ty=goalDy;}const d=hypot(tx,ty)||1;tx/=d;ty/=d;force=470;glueMsg='✦  GLUE FINISH · PASS!';}ball.glued=null;ball.vx=tx*force+p.vx*.35;ball.vy=ty*force+p.vy*.35;p.glue=0;p.kickFlash=.22;glueMsgTime=1.1;particleBurst(ball.x,ball.y,gold,18,1);shake=Math.max(shake,1.5);}
function updateGlue(dt){for(const p of players){if(p.glueCd>0)p.glueCd=Math.max(0,p.glueCd-dt);if(p.glue>0){p.glue=Math.max(0,p.glue-dt);p.glueFx+=dt*8;if(p.glue<=0)finishGlue(p);}}if(glueMsgTime>0)glueMsgTime=Math.max(0,glueMsgTime-dt);}

