let id=0,pending={};ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending[m.id]){pending[m.id](m);delete pending[m.id]}else if(m.method==='Runtime.exceptionThrown')console.log('EXCEPTION',m.params.exceptionDetails.text)};
const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending[n]=resolve;ws.send(JSON.stringify({id:n,method,params}))});
const evalJS=async expression=>(await call('Runtime.evaluate',{expression,returnByValue:true})).result.result.value;
const wait=ms=>new Promise(r=>setTimeout(r,ms));
await call('Runtime.enable');await call('Page.navigate',{url:'http://localhost:8765'});await wait(300);
await evalJS("document.querySelector('[data-mode=pessi]').click()");
await call('Input.dispatchKeyEvent',{type:'keyDown',key:'ArrowUp',code:'ArrowUp',windowsVirtualKeyCode:38});await wait(350);await call('Input.dispatchKeyEvent',{type:'keyUp',key:'ArrowUp',code:'ArrowUp',windowsVirtualKeyCode:38});
const before=await evalJS("({timer:document.querySelector('#timer').textContent,status:document.querySelector('#glueStatus').textContent})");
await call('Input.dispatchKeyEvent',{type:'keyDown',key:'e',code:'KeyE',windowsVirtualKeyCode:69});await call('Input.dispatchKeyEvent',{type:'keyUp',key:'e',code:'KeyE',windowsVirtualKeyCode:69});await wait(250);
const active=await evalJS("({status:document.querySelector('#glueStatus').textContent,active:document.querySelector('#glue').classList.contains('active-ability'),ring:document.querySelector('#glueCool').style.getPropertyValue('--cool')})");
let transitions=[],last=active.status;for(let i=0;i<34;i++){await wait(150);const status=await evalJS("document.querySelector('#glueStatus').textContent");if(status!==last){transitions.push({after:((i+1)*.15).toFixed(2)+'s',status});last=status}}
const after=await evalJS("({status:document.querySelector('#glueStatus').textContent,active:document.querySelector('#glue').classList.contains('active-ability'),timer:document.querySelector('#timer').textContent,ring:document.querySelector('#glueCool').style.getPropertyValue('--cool')})");
console.log(JSON.stringify({before,active,transitions,after},null,2));ws.close();
})().catch(e=>{console.error(e);process.exit(1)});
